-- Extension additive du Support. Les dossiers sans parcours restent inchangés.
CREATE TABLE support."T_ModeleProcessus" (
    "ID_Modele" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IdEntiteFk" integer NOT NULL REFERENCES systeme."T_Entite"("IdEntite") ON DELETE RESTRICT,
    "Nom" varchar(120) NOT NULL CHECK (length(btrim("Nom")) BETWEEN 1 AND 120),
    "ID_TypeSupportFk" integer NOT NULL REFERENCES referentiel."T_Generique"("ID_Generique") ON DELETE RESTRICT,
    "Actif" boolean NOT NULL DEFAULT true,
    "Revision" integer NOT NULL DEFAULT 1 CHECK ("Revision" > 0),
    "CreePar" integer NOT NULL REFERENCES systeme."T_Utilisateurs"("IdUser") ON DELETE RESTRICT,
    "CreeLe" timestamptz NOT NULL DEFAULT clock_timestamp(),
    "ModifieLe" timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE UNIQUE INDEX ux_support_modele_nom
ON support."T_ModeleProcessus" ("IdEntiteFk", lower(btrim("Nom")));

CREATE TABLE support."T_VersionProcessus" (
    "ID_Version" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ID_ModeleFk" bigint NOT NULL REFERENCES support."T_ModeleProcessus"("ID_Modele") ON DELETE RESTRICT,
    "Numero" integer NOT NULL CHECK ("Numero" > 0),
    "Definition" jsonb NOT NULL,
    "Actif" boolean NOT NULL DEFAULT true,
    "CreePar" integer NOT NULL REFERENCES systeme."T_Utilisateurs"("IdUser") ON DELETE RESTRICT,
    "CreeLe" timestamptz NOT NULL DEFAULT clock_timestamp(),
    "RequestId" uuid,
    "PayloadHash" text,
    UNIQUE ("ID_ModeleFk", "Numero"),
    CONSTRAINT ck_support_definition_processus CHECK (
        jsonb_typeof("Definition") = 'object'
        AND CASE WHEN jsonb_typeof("Definition"->'stages') = 'array'
            THEN jsonb_array_length("Definition"->'stages') BETWEEN 1 AND 30 ELSE false END
    ),
    CONSTRAINT ck_support_version_rejeu CHECK (
        ("RequestId" IS NULL AND "PayloadHash" IS NULL)
        OR ("RequestId" IS NOT NULL AND "PayloadHash" IS NOT NULL AND "PayloadHash" ~ '^[a-f0-9]{64}$')
    )
);

CREATE UNIQUE INDEX ux_support_version_rejeu ON support."T_VersionProcessus" ("CreePar", "RequestId")
WHERE "RequestId" IS NOT NULL;

CREATE TABLE support."T_ParcoursSupport" (
    "ID_SupportFk" bigint PRIMARY KEY REFERENCES support."T_Support"("ID_Support") ON DELETE RESTRICT,
    "IdEntiteFk" integer NOT NULL REFERENCES systeme."T_Entite"("IdEntite") ON DELETE RESTRICT,
    "ID_VersionFk" bigint NOT NULL REFERENCES support."T_VersionProcessus"("ID_Version") ON DELETE RESTRICT,
    "DemarreLe" timestamptz NOT NULL DEFAULT clock_timestamp(),
    "EcheanceGlobale" timestamptz,
    "TermineLe" timestamptz,
    "Revision" integer NOT NULL DEFAULT 1 CHECK ("Revision" > 0),
    CONSTRAINT ck_support_parcours_dates CHECK (
        isfinite("DemarreLe") AND
        ("EcheanceGlobale" IS NULL OR (isfinite("EcheanceGlobale") AND "EcheanceGlobale" > "DemarreLe")) AND
        ("TermineLe" IS NULL OR (isfinite("TermineLe") AND "TermineLe" >= "DemarreLe"))
    )
);

CREATE INDEX ix_support_parcours_entite ON support."T_ParcoursSupport" ("IdEntiteFk", "ID_SupportFk");
CREATE INDEX ix_support_parcours_echeance ON support."T_ParcoursSupport" ("EcheanceGlobale", "ID_SupportFk")
WHERE "TermineLe" IS NULL AND "EcheanceGlobale" IS NOT NULL;

CREATE TABLE support."T_EtapeParcours" (
    "ID_Etape" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ID_SupportFk" bigint NOT NULL REFERENCES support."T_ParcoursSupport"("ID_SupportFk") ON DELETE RESTRICT,
    "Position" integer NOT NULL CHECK ("Position" BETWEEN 1 AND 30),
    "EntreeLe" timestamptz NOT NULL DEFAULT clock_timestamp(),
    "Echeance" timestamptz,
    "ReceptionLe" timestamptz,
    "SortieLe" timestamptz,
    "ID_ResponsableFk" integer REFERENCES systeme."T_Utilisateurs"("IdUser") ON DELETE RESTRICT,
    "ID_ServiceFk" integer REFERENCES referentiel."T_Generique"("ID_Generique") ON DELETE RESTRICT,
    "Blocage" text CHECK (length(btrim("Blocage")) BETWEEN 1 AND 2000),
    "ID_MotifBlocageFk" integer REFERENCES referentiel."T_Generique"("ID_Generique") ON DELETE RESTRICT,
    UNIQUE ("ID_SupportFk", "ID_Etape"),
    CONSTRAINT ck_support_etape_dates CHECK (
        isfinite("EntreeLe") AND
        ("Echeance" IS NULL OR (isfinite("Echeance") AND "Echeance" > "EntreeLe")) AND
        ("ReceptionLe" IS NULL OR (isfinite("ReceptionLe") AND "ReceptionLe" >= "EntreeLe")) AND
        ("SortieLe" IS NULL OR (isfinite("SortieLe") AND "SortieLe" >= coalesce("ReceptionLe", "EntreeLe")))
    ),
    CONSTRAINT ck_support_etape_motif CHECK ("ID_MotifBlocageFk" IS NULL OR "Blocage" IS NOT NULL)
);

CREATE UNIQUE INDEX ux_support_etape_active ON support."T_EtapeParcours" ("ID_SupportFk") WHERE "SortieLe" IS NULL;
CREATE INDEX ix_support_etape_echeance ON support."T_EtapeParcours" ("Echeance", "ID_SupportFk")
WHERE "SortieLe" IS NULL AND "Echeance" IS NOT NULL;

CREATE TABLE support."T_EvenementParcours" (
    "ID_Evenement" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ID_SupportFk" bigint NOT NULL REFERENCES support."T_ParcoursSupport"("ID_SupportFk") ON DELETE RESTRICT,
    "ID_EtapeFk" bigint,
    "Action" text NOT NULL CHECK (length(btrim("Action")) BETWEEN 1 AND 40),
    "AuteurFk" integer NOT NULL REFERENCES systeme."T_Utilisateurs"("IdUser") ON DELETE RESTRICT,
    "DateEvenement" timestamptz NOT NULL DEFAULT clock_timestamp() CHECK (isfinite("DateEvenement")),
    "Motif" text CHECK (length("Motif") <= 2000),
    "Donnees" jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof("Donnees") = 'object'),
    "RequestId" uuid NOT NULL,
    "PayloadHash" text NOT NULL CHECK ("PayloadHash" ~ '^[a-f0-9]{64}$'),
    UNIQUE ("ID_SupportFk", "RequestId"),
    FOREIGN KEY ("ID_SupportFk", "ID_EtapeFk")
        REFERENCES support."T_EtapeParcours"("ID_SupportFk", "ID_Etape") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX ux_support_validation_par_auteur ON support."T_EvenementParcours" ("ID_EtapeFk", "AuteurFk")
WHERE "Action" = 'approve' AND "ID_EtapeFk" IS NOT NULL;
CREATE INDEX ix_support_evenement_historique ON support."T_EvenementParcours" ("ID_SupportFk", "DateEvenement", "ID_Evenement");

CREATE TABLE support."T_AlerteParcours" (
    "ID_Alerte" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ID_SupportFk" bigint NOT NULL REFERENCES support."T_ParcoursSupport"("ID_SupportFk") ON DELETE RESTRICT,
    "ID_EtapeFk" bigint,
    "Type" text NOT NULL CHECK ("Type" IN ('global', 'stage')),
    "Occurrence" integer NOT NULL CHECK ("Occurrence" >= 0),
    "CreeLe" timestamptz NOT NULL DEFAULT clock_timestamp(),
    "Statut" text NOT NULL DEFAULT 'pending' CHECK ("Statut" IN ('pending', 'sent', 'failed')),
    "Erreur" text CHECK (length("Erreur") <= 500),
    "DestinataireFk" integer REFERENCES systeme."T_Utilisateurs"("IdUser") ON DELETE RESTRICT,
    "ID_CommunicationFk" integer UNIQUE REFERENCES communication."T_Communication"("IdCommunication") ON DELETE RESTRICT,
    "TraiteLe" timestamptz,
    UNIQUE NULLS NOT DISTINCT ("ID_SupportFk", "ID_EtapeFk", "Type", "Occurrence"),
    FOREIGN KEY ("ID_SupportFk", "ID_EtapeFk")
        REFERENCES support."T_EtapeParcours"("ID_SupportFk", "ID_Etape") ON DELETE RESTRICT,
    CONSTRAINT ck_support_alerte_type CHECK (("Type" = 'stage') = ("ID_EtapeFk" IS NOT NULL)),
    CONSTRAINT ck_support_alerte_preuve CHECK (
        ("Statut" = 'sent' AND "ID_CommunicationFk" IS NOT NULL AND "DestinataireFk" IS NOT NULL AND "TraiteLe" IS NOT NULL AND "Erreur" IS NULL)
        OR ("Statut" = 'failed' AND "ID_CommunicationFk" IS NULL AND "TraiteLe" IS NOT NULL AND nullif(btrim("Erreur"), '') IS NOT NULL)
        OR ("Statut" = 'pending' AND "ID_CommunicationFk" IS NULL AND "TraiteLe" IS NULL AND "Erreur" IS NULL)
    )
);

-- Les motifs utilisent les mêmes catégories et correspondances que les autres choix métier.
DO $referentiel$
DECLARE categorie integer; nombre integer;
BEGIN
    SELECT min("ID_CategorieGenerique"), count(*) INTO categorie, nombre
    FROM referentiel."T_CategorieGenerique"
    WHERE "IdEntiteFk" IS NULL AND lower(btrim("NomCategorieGenerique")) = lower('Motif de blocage Support');
    IF nombre > 1 THEN RAISE EXCEPTION 'Catégorie commune des motifs de blocage Support ambiguë.'; END IF;
    IF categorie IS NULL THEN
        INSERT INTO referentiel."T_CategorieGenerique" ("NomCategorieGenerique", "ModuleCategorieGenerique", "ValideCategorieGenerique")
        VALUES ('Motif de blocage Support', 'M_SUPPORT', true)
        RETURNING "ID_CategorieGenerique" INTO categorie;
    END IF;
    INSERT INTO referentiel."T_ChampReferentiel" (
        "SchemaName", "TableName", "ColumnName", "ChampLabel", "ModuleName",
        "ID_CategorieDefautFk", "AliasSourceKeys", "CanConfigure", "SupportsEntityScope"
    ) VALUES (
        'support', 'T_EtapeParcours', 'ID_MotifBlocageFk', 'Motif de blocage', 'support',
        categorie, ARRAY['support.processBlockers'], true, true
    );
END $referentiel$;

CREATE FUNCTION support.tr_processus_modele() RETURNS trigger
LANGUAGE plpgsql SET search_path TO pg_catalog AS $fn$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Désactivez le modèle pour conserver les versions.' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NOT EXISTS (
            SELECT FROM systeme."T_Utilisateurs" u WHERE u."IdUser" = NEW."CreePar" AND u."ValideUser"
            AND (u."IdEntiteFk" = NEW."IdEntiteFk" OR u."Is_Admin")
        ) OR NOT referentiel.fn_valider_reference_champ('support', 'T_Support', 'ID_TypeSupportFk', NEW."ID_TypeSupportFk", NEW."IdEntiteFk") THEN
            RAISE EXCEPTION 'Auteur ou type incompatible avec l’entreprise du modèle.' USING ERRCODE = '23514';
        END IF;
    ELSIF ROW(NEW."ID_Modele", NEW."IdEntiteFk", NEW."ID_TypeSupportFk", NEW."CreePar", NEW."CreeLe")
        IS DISTINCT FROM ROW(OLD."ID_Modele", OLD."IdEntiteFk", OLD."ID_TypeSupportFk", OLD."CreePar", OLD."CreeLe") THEN
        RAISE EXCEPTION 'Identité, type et entreprise du modèle immuables.' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $fn$;

CREATE FUNCTION support.tr_processus_version() RETURNS trigger
LANGUAGE plpgsql SET search_path TO pg_catalog AS $fn$
DECLARE entreprise integer;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'Publiez une nouvelle version du modèle.' USING ERRCODE = '23514';
    END IF;
    SELECT "IdEntiteFk" INTO entreprise FROM support."T_ModeleProcessus" WHERE "ID_Modele" = NEW."ID_ModeleFk" FOR UPDATE;
    IF entreprise IS NULL OR NOT EXISTS (
        SELECT FROM systeme."T_Utilisateurs" u WHERE u."IdUser" = NEW."CreePar" AND u."ValideUser"
        AND (u."IdEntiteFk" = entreprise OR u."Is_Admin")
    ) THEN
        RAISE EXCEPTION 'Auteur hors entreprise du modèle.' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $fn$;

CREATE FUNCTION support.tr_processus_parcours() RETURNS trigger
LANGUAGE plpgsql SET search_path TO pg_catalog AS $fn$
DECLARE dossier support."T_Support"; modele support."T_ModeleProcessus";
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'L’historique du parcours est conservé.' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        IF ROW(NEW."ID_SupportFk", NEW."IdEntiteFk", NEW."ID_VersionFk", NEW."DemarreLe", NEW."EcheanceGlobale")
           IS DISTINCT FROM ROW(OLD."ID_SupportFk", OLD."IdEntiteFk", OLD."ID_VersionFk", OLD."DemarreLe", OLD."EcheanceGlobale")
           OR OLD."TermineLe" IS NOT NULL THEN
            RAISE EXCEPTION 'Le dossier et la version du parcours sont immuables.' USING ERRCODE = '23514';
        END IF;
        IF NEW."TermineLe" IS NOT NULL AND EXISTS (
            SELECT FROM support."T_EtapeParcours" e WHERE e."ID_SupportFk" = OLD."ID_SupportFk" AND e."SortieLe" IS NULL
        ) THEN
            RAISE EXCEPTION 'Terminez l’étape courante avant de terminer le parcours.' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    SELECT * INTO dossier FROM support."T_Support" WHERE "ID_Support" = NEW."ID_SupportFk" FOR UPDATE;
    SELECT m.* INTO modele FROM support."T_ModeleProcessus" m
    JOIN support."T_VersionProcessus" v ON v."ID_ModeleFk" = m."ID_Modele"
    WHERE v."ID_Version" = NEW."ID_VersionFk" AND v."Actif" FOR SHARE OF m;
    IF dossier."ID_Support" IS NULL OR dossier."Archive"
       OR support.fn_etat_support(dossier."CircuitSnapshot", dossier."ID_StatutFk") IN ('resolved', 'closed')
       OR dossier."IdEntiteFk" IS DISTINCT FROM NEW."IdEntiteFk"
       OR modele."IdEntiteFk" IS DISTINCT FROM NEW."IdEntiteFk"
       OR modele."ID_TypeSupportFk" IS DISTINCT FROM dossier."ID_TypeSupportFk"
       OR modele."Actif" IS NOT TRUE
       OR NEW."ID_VersionFk" IS DISTINCT FROM (
           SELECT "ID_Version" FROM support."T_VersionProcessus" WHERE "ID_ModeleFk" = modele."ID_Modele"
           ORDER BY "Numero" DESC LIMIT 1
       ) THEN
        RAISE EXCEPTION 'Modèle inactif, version obsolète ou incompatible avec le dossier.' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $fn$;

CREATE FUNCTION support.tr_processus_etape() RETURNS trigger
LANGUAGE plpgsql SET search_path TO pg_catalog AS $fn$
DECLARE parcours support."T_ParcoursSupport"; etapes integer;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'L’historique des étapes est conservé.' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND (
        OLD."SortieLe" IS NOT NULL
        OR ROW(NEW."ID_Etape", NEW."ID_SupportFk", NEW."Position", NEW."EntreeLe", NEW."Echeance")
           IS DISTINCT FROM ROW(OLD."ID_Etape", OLD."ID_SupportFk", OLD."Position", OLD."EntreeLe", OLD."Echeance")
        OR (OLD."ReceptionLe" IS NOT NULL AND NEW."ReceptionLe" IS DISTINCT FROM OLD."ReceptionLe")
    ) THEN
        RAISE EXCEPTION 'Une étape terminée, ses dates et son identité sont conservées.' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO parcours FROM support."T_ParcoursSupport" WHERE "ID_SupportFk" = NEW."ID_SupportFk" FOR UPDATE;
    SELECT jsonb_array_length("Definition"->'stages') INTO etapes FROM support."T_VersionProcessus"
    WHERE "ID_Version" = parcours."ID_VersionFk";
    IF parcours."ID_SupportFk" IS NULL OR parcours."TermineLe" IS NOT NULL OR NEW."Position" > etapes
       OR NEW."EntreeLe" < parcours."DemarreLe" THEN
        RAISE EXCEPTION 'Étape incompatible avec le parcours du dossier.' USING ERRCODE = '23514';
    END IF;
    IF (TG_OP = 'INSERT' OR NEW."ID_ResponsableFk" IS DISTINCT FROM OLD."ID_ResponsableFk")
       AND NEW."ID_ResponsableFk" IS NOT NULL AND NOT EXISTS (
           SELECT FROM systeme."T_Utilisateurs" u WHERE u."IdUser" = NEW."ID_ResponsableFk"
           AND u."IdEntiteFk" = parcours."IdEntiteFk" AND u."ValideUser"
       ) THEN
        RAISE EXCEPTION 'Responsable hors entreprise du dossier ou inactif.' USING ERRCODE = '23514';
    END IF;
    IF (TG_OP = 'INSERT' OR NEW."ID_ServiceFk" IS DISTINCT FROM OLD."ID_ServiceFk")
       AND NOT referentiel.fn_reference_visible(NEW."ID_ServiceFk", parcours."IdEntiteFk")
       AND NEW."ID_ServiceFk" IS NOT NULL THEN
        RAISE EXCEPTION 'Service hors entreprise du dossier.' USING ERRCODE = '23514';
    END IF;
    IF (TG_OP = 'INSERT' OR NEW."ID_MotifBlocageFk" IS DISTINCT FROM OLD."ID_MotifBlocageFk")
       AND NOT referentiel.fn_reference_visible(NEW."ID_MotifBlocageFk", parcours."IdEntiteFk")
       AND NEW."ID_MotifBlocageFk" IS NOT NULL THEN
        RAISE EXCEPTION 'Motif hors entreprise du dossier.' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $fn$;

CREATE FUNCTION support.tr_processus_evenement() RETURNS trigger
LANGUAGE plpgsql SET search_path TO pg_catalog AS $fn$
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'Les événements du parcours sont immuables.' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
        SELECT FROM systeme."T_Utilisateurs" u
        JOIN support."T_ParcoursSupport" p ON p."ID_SupportFk" = NEW."ID_SupportFk"
        WHERE u."IdUser" = NEW."AuteurFk" AND u."ValideUser" AND (u."IdEntiteFk" = p."IdEntiteFk" OR u."Is_Admin")
    ) THEN
        RAISE EXCEPTION 'Auteur hors entreprise du dossier.' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $fn$;

CREATE FUNCTION support.tr_processus_alerte() RETURNS trigger
LANGUAGE plpgsql SET search_path TO pg_catalog AS $fn$
DECLARE entreprise integer;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Le suivi des alertes est conservé.' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND (
        OLD."Statut" = 'sent' OR
        ROW(NEW."ID_Alerte", NEW."ID_SupportFk", NEW."ID_EtapeFk", NEW."Type", NEW."Occurrence", NEW."CreeLe")
        IS DISTINCT FROM ROW(OLD."ID_Alerte", OLD."ID_SupportFk", OLD."ID_EtapeFk", OLD."Type", OLD."Occurrence", OLD."CreeLe")
    ) THEN
        RAISE EXCEPTION 'L’identité et les envois réussis des alertes sont immuables.' USING ERRCODE = '23514';
    END IF;
    IF NEW."DestinataireFk" IS NOT NULL THEN
        SELECT "IdEntiteFk" INTO entreprise FROM support."T_ParcoursSupport" WHERE "ID_SupportFk" = NEW."ID_SupportFk";
        IF NOT EXISTS (
            SELECT FROM systeme."T_Utilisateurs" WHERE "IdUser" = NEW."DestinataireFk" AND "IdEntiteFk" = entreprise AND "ValideUser"
        ) THEN
            RAISE EXCEPTION 'Destinataire hors entreprise du dossier ou inactif.' USING ERRCODE = '23514';
        END IF;
        IF NEW."ID_CommunicationFk" IS NOT NULL AND NOT EXISTS (
            SELECT FROM communication."T_Communication" n
            WHERE n."IdCommunication" = NEW."ID_CommunicationFk" AND n."IdUserFk" = NEW."DestinataireFk"
              AND n."IdEntiteFk" = entreprise AND n."IdAnnonceFk" IS NULL
        ) THEN
            RAISE EXCEPTION 'Notification incompatible avec le destinataire de l’alerte.' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END $fn$;

CREATE TRIGGER a_processus_modele BEFORE INSERT OR UPDATE OR DELETE ON support."T_ModeleProcessus"
FOR EACH ROW EXECUTE FUNCTION support.tr_processus_modele();
CREATE TRIGGER a_processus_version BEFORE INSERT OR UPDATE OR DELETE ON support."T_VersionProcessus"
FOR EACH ROW EXECUTE FUNCTION support.tr_processus_version();
CREATE TRIGGER a_processus_parcours BEFORE INSERT OR UPDATE OR DELETE ON support."T_ParcoursSupport"
FOR EACH ROW EXECUTE FUNCTION support.tr_processus_parcours();
CREATE TRIGGER a_processus_etape BEFORE INSERT OR UPDATE OR DELETE ON support."T_EtapeParcours"
FOR EACH ROW EXECUTE FUNCTION support.tr_processus_etape();
CREATE TRIGGER a_processus_evenement BEFORE INSERT OR UPDATE OR DELETE ON support."T_EvenementParcours"
FOR EACH ROW EXECUTE FUNCTION support.tr_processus_evenement();
CREATE TRIGGER a_processus_alerte BEFORE INSERT OR UPDATE OR DELETE ON support."T_AlerteParcours"
FOR EACH ROW EXECUTE FUNCTION support.tr_processus_alerte();

CREATE VIEW support."V_ParcoursSupport" AS
SELECT p."ID_SupportFk", p."IdEntiteFk", p."ID_VersionFk", p."DemarreLe", p."EcheanceGlobale",
    p."TermineLe", p."Revision", e."ID_Etape" AS "ID_EtapeCourante", e."Position", e."EntreeLe",
    e."Echeance" AS "EcheanceEtape", e."ReceptionLe", e."ID_ResponsableFk", e."ID_ServiceFk",
    e."Blocage", e."ID_MotifBlocageFk",
    (v."Definition"->'stages'->(e."Position" - 1))->>'name' AS "NomEtape",
    coalesce(p."TermineLe" IS NULL AND p."EcheanceGlobale" < statement_timestamp(), false) AS "EnRetardGlobal",
    coalesce(p."TermineLe" IS NULL AND e."Echeance" < statement_timestamp(), false) AS "EnRetardEtape"
FROM support."T_ParcoursSupport" p
JOIN support."T_VersionProcessus" v ON v."ID_Version" = p."ID_VersionFk"
LEFT JOIN support."T_EtapeParcours" e ON e."ID_SupportFk" = p."ID_SupportFk" AND e."SortieLe" IS NULL;

COMMENT ON TABLE support."T_ModeleProcessus" IS 'Identité durable d’un modèle de suivi d’une entreprise. Son activation ne concerne que les nouveaux parcours.';
COMMENT ON COLUMN support."T_ModeleProcessus"."ID_Modele" IS 'Identifiant stable du modèle.';
COMMENT ON COLUMN support."T_ModeleProcessus"."IdEntiteFk" IS 'Entreprise propriétaire du modèle.';
COMMENT ON COLUMN support."T_ModeleProcessus"."Nom" IS 'Libellé courant, unique dans l’entreprise.';
COMMENT ON COLUMN support."T_ModeleProcessus"."ID_TypeSupportFk" IS 'Type du dossier issu du référentiel Support.';
COMMENT ON COLUMN support."T_ModeleProcessus"."Actif" IS 'Autorise les nouveaux dossiers à démarrer ce parcours.';
COMMENT ON COLUMN support."T_ModeleProcessus"."Revision" IS 'Révision utilisée pour contrôler la modification concurrente du modèle.';
COMMENT ON COLUMN support."T_ModeleProcessus"."CreePar" IS 'Auteur de la création du modèle.';
COMMENT ON COLUMN support."T_ModeleProcessus"."CreeLe" IS 'Date et heure de création du modèle.';
COMMENT ON COLUMN support."T_ModeleProcessus"."ModifieLe" IS 'Date et heure de la dernière publication ou désactivation.';

COMMENT ON TABLE support."T_VersionProcessus" IS 'Règles immuables successives du modèle. Un dossier engagé conserve la version qu’il a démarrée.';
COMMENT ON COLUMN support."T_VersionProcessus"."ID_Version" IS 'Identifiant de la version publiée.';
COMMENT ON COLUMN support."T_VersionProcessus"."ID_ModeleFk" IS 'Modèle auquel appartient la version.';
COMMENT ON COLUMN support."T_VersionProcessus"."Numero" IS 'Numéro de version au sein du modèle.';
COMMENT ON COLUMN support."T_VersionProcessus"."Definition" IS 'Instantané des étapes ordonnées, validations, affectations, motifs et délais configurés.';
COMMENT ON COLUMN support."T_VersionProcessus"."Actif" IS 'Activation du modèle au moment de la publication.';
COMMENT ON COLUMN support."T_VersionProcessus"."CreePar" IS 'Auteur de la publication.';
COMMENT ON COLUMN support."T_VersionProcessus"."CreeLe" IS 'Date et heure de publication.';
COMMENT ON COLUMN support."T_VersionProcessus"."RequestId" IS 'Identifiant de requête d’édition permettant le rejeu sans nouvelle version.';
COMMENT ON COLUMN support."T_VersionProcessus"."PayloadHash" IS 'Empreinte du contenu associé à l’identifiant de requête.';

COMMENT ON TABLE support."T_ParcoursSupport" IS 'Parcours facultatif d’un dossier Support, lié à une version et distinct de son état général.';
COMMENT ON COLUMN support."T_ParcoursSupport"."ID_SupportFk" IS 'Dossier suivi, à raison d’un parcours au maximum.';
COMMENT ON COLUMN support."T_ParcoursSupport"."IdEntiteFk" IS 'Entreprise propriétaire du dossier et du modèle.';
COMMENT ON COLUMN support."T_ParcoursSupport"."ID_VersionFk" IS 'Version immuable choisie au démarrage.';
COMMENT ON COLUMN support."T_ParcoursSupport"."DemarreLe" IS 'Point de départ du délai global.';
COMMENT ON COLUMN support."T_ParcoursSupport"."EcheanceGlobale" IS 'Échéance globale calculée au démarrage à partir des règles de la version.';
COMMENT ON COLUMN support."T_ParcoursSupport"."TermineLe" IS 'Fin du parcours et du décompte global, distincte de la clôture du dossier.';
COMMENT ON COLUMN support."T_ParcoursSupport"."Revision" IS 'Révision du parcours utilisée pour contrôler les actions simultanées.';

COMMENT ON TABLE support."T_EtapeParcours" IS 'Passages du dossier dans ses étapes, avec un nouveau passage en cas de retour et une seule étape courante.';
COMMENT ON COLUMN support."T_EtapeParcours"."ID_Etape" IS 'Identifiant du passage dans une étape.';
COMMENT ON COLUMN support."T_EtapeParcours"."ID_SupportFk" IS 'Dossier auquel appartient le passage.';
COMMENT ON COLUMN support."T_EtapeParcours"."Position" IS 'Rang commençant à un dans les étapes de la version applicable.';
COMMENT ON COLUMN support."T_EtapeParcours"."EntreeLe" IS 'Transmission à l’étape et début de son délai.';
COMMENT ON COLUMN support."T_EtapeParcours"."Echeance" IS 'Échéance propre au passage, calculée lors de son ouverture.';
COMMENT ON COLUMN support."T_EtapeParcours"."ReceptionLe" IS 'Réception par le destinataire, si enregistrée.';
COMMENT ON COLUMN support."T_EtapeParcours"."SortieLe" IS 'Transmission, retour ou fin du passage. NULL désigne l’étape courante.';
COMMENT ON COLUMN support."T_EtapeParcours"."ID_ResponsableFk" IS 'Responsable individuel du passage, appartenant à l’entreprise du dossier.';
COMMENT ON COLUMN support."T_EtapeParcours"."ID_ServiceFk" IS 'Service affectataire issu du référentiel commun ou propre à l’entreprise.';
COMMENT ON COLUMN support."T_EtapeParcours"."Blocage" IS 'Justification du blocage courant. Les blocages successifs sont tracés dans les événements.';
COMMENT ON COLUMN support."T_EtapeParcours"."ID_MotifBlocageFk" IS 'Motif catégoriel facultatif du blocage courant.';

COMMENT ON TABLE support."T_EvenementParcours" IS 'Journal immuable des actions du parcours, des validations et des justifications. Identifie les requêtes rejouées.';
COMMENT ON COLUMN support."T_EvenementParcours"."ID_Evenement" IS 'Identifiant stable de l’événement.';
COMMENT ON COLUMN support."T_EvenementParcours"."ID_SupportFk" IS 'Dossier auquel appartient l’événement.';
COMMENT ON COLUMN support."T_EvenementParcours"."ID_EtapeFk" IS 'Passage concerné si l’action porte sur une étape.';
COMMENT ON COLUMN support."T_EvenementParcours"."Action" IS 'Code de l’action effectuée dans le parcours.';
COMMENT ON COLUMN support."T_EvenementParcours"."AuteurFk" IS 'Auteur authentifié de l’action.';
COMMENT ON COLUMN support."T_EvenementParcours"."DateEvenement" IS 'Date et heure de l’action.';
COMMENT ON COLUMN support."T_EvenementParcours"."Motif" IS 'Justification utile de l’action.';
COMMENT ON COLUMN support."T_EvenementParcours"."Donnees" IS 'Informations de suivi et identifiants de preuve, sans copie de fichiers.';
COMMENT ON COLUMN support."T_EvenementParcours"."RequestId" IS 'Identifiant de requête unique dans le dossier.';
COMMENT ON COLUMN support."T_EvenementParcours"."PayloadHash" IS 'Empreinte du contenu de la requête pour distinguer le rejeu d’une autre action.';

COMMENT ON TABLE support."T_AlerteParcours" IS 'Occurrences d’alerte de délai, avec suivi de la remise et de son éventuel échec.';
COMMENT ON COLUMN support."T_AlerteParcours"."ID_Alerte" IS 'Identifiant stable de l’alerte.';
COMMENT ON COLUMN support."T_AlerteParcours"."ID_SupportFk" IS 'Dossier concerné.';
COMMENT ON COLUMN support."T_AlerteParcours"."ID_EtapeFk" IS 'Passage concerné pour une échéance d’étape.';
COMMENT ON COLUMN support."T_AlerteParcours"."Type" IS 'Portée de l’alerte, globale ou liée à une étape.';
COMMENT ON COLUMN support."T_AlerteParcours"."Occurrence" IS 'Rang de la notification initiale et de ses relances pour la même échéance.';
COMMENT ON COLUMN support."T_AlerteParcours"."CreeLe" IS 'Date et heure de la première prise en charge de cette occurrence.';
COMMENT ON COLUMN support."T_AlerteParcours"."Statut" IS 'État du traitement de la remise de la notification.';
COMMENT ON COLUMN support."T_AlerteParcours"."Erreur" IS 'Cause fonctionnelle de l’échec, sans détail technique sensible.';
COMMENT ON COLUMN support."T_AlerteParcours"."DestinataireFk" IS 'Compte de l’entreprise destinataire de la notification.';
COMMENT ON COLUMN support."T_AlerteParcours"."ID_CommunicationFk" IS 'Notification privée remise au destinataire.';
COMMENT ON COLUMN support."T_AlerteParcours"."TraiteLe" IS 'Date et heure du résultat de traitement.';

COMMENT ON FUNCTION support.tr_processus_modele() IS 'Vérifie l’auteur, la portée et le type du modèle et conserve son identité.';
COMMENT ON FUNCTION support.tr_processus_version() IS 'Garantit l’immutabilité des versions et la portée de l’auteur de publication.';
COMMENT ON FUNCTION support.tr_processus_parcours() IS 'Lie le dossier et sa version initiale dans une même entreprise et protège les parcours terminés.';
COMMENT ON FUNCTION support.tr_processus_etape() IS 'Protège les passages historiques, la position et la portée du service, du responsable et du motif.';
COMMENT ON FUNCTION support.tr_processus_evenement() IS 'Contrôle la portée de l’auteur et garantit l’immutabilité du journal.';
COMMENT ON FUNCTION support.tr_processus_alerte() IS 'Vérifie la notification privée, la portée de son destinataire et la conservation des envois.';

COMMENT ON TRIGGER a_processus_modele ON support."T_ModeleProcessus" IS 'Garde d’identité et de portée du modèle.';
COMMENT ON TRIGGER a_processus_version ON support."T_VersionProcessus" IS 'Protection des versions déjà publiées.';
COMMENT ON TRIGGER a_processus_parcours ON support."T_ParcoursSupport" IS 'Vérification du dossier et de sa version au démarrage.';
COMMENT ON TRIGGER a_processus_etape ON support."T_EtapeParcours" IS 'Garde de cohérence des passages et de leurs affectations.';
COMMENT ON TRIGGER a_processus_evenement ON support."T_EvenementParcours" IS 'Protection du journal de suivi et de son auteur.';
COMMENT ON TRIGGER a_processus_alerte ON support."T_AlerteParcours" IS 'Protection de l’identité de l’alerte et de sa notification.';

